```json
{
  "audits": [
    {
      "claim_text": "Kestrabel Ventures is a London-based firm",
      "claim_type": "other",
      "verdict": "verified",
      "evidence": "firm_profiles[0].hq=London, UK"
    },
    {
      "claim_text": "founded in 2012",
      "claim_type": "other",
      "verdict": "verified",
      "evidence": "firm_profiles[0].description='...founded in 2012.'"
    },
    {
      "claim_text": "It invests at Seed and Series A",
      "claim_type": "other",
      "verdict": "verified",
      "evidence": "firm_profiles[0].stages=[Seed, Series A]"
    },
    {
      "claim_text": "its two focus areas are cybersecurity and developer tools",
      "claim_type": "other",
      "verdict": "verified",
      "evidence": "firm_profiles[0].focus_areas=[cybersecurity, devtools]"
    },
    {
      "claim_text": "When I searched for seed-stage cybersecurity investors in the UK, Kestrabel was the only firm that came back.",
      "claim_type": "other",
      "verdict": "unverifiable",
      "evidence": null
    },
    {
      "claim_text": "Its cheques run from €1M to €5M",
      "claim_type": "ticket_band",
      "verdict": "verified",
      "evidence": "firm_profiles[0].cheque_range=1000000 – 5000000"
    },
    {
      "claim_text": "Two of its three portfolio companies are in security.",
      "claim_type": "portfolio_company",
      "verdict": "verified",
      "evidence": "firm_profiles[1].focus_areas=[cybersecurity: 2, devtools: 1]; portfolio_companies[].sector"
    },
    {
      "claim_text": "Tarnwick Security, backed in 2020, provides managed detection for small law firms that have no in-house security staff.",
      "claim_type": "portfolio_company",
      "verdict": "verified",
      "evidence": "portfolio_companies[].name=Tarnwick Security (description: [Kestrabel Ventures, 2020] Managed detection for small law firms with no in-house security staff)"
    },
    {
      "claim_text": "Rukvane Security runs a platform that helps mid-market companies with older identity systems roll out phishing-resistant passkeys.",
      "claim_type": "portfolio_company",
      "verdict": "verified",
      "evidence": "portfolio_companies[].name=Rukvane Security (description: Phishing-resistant passkey rollout platform for mid-market companies with legacy identity stacks)"
    },
    {
      "claim_text": "Kestrabel led a €3.5M seed round in Rukvane, announced on 15 April 2026",
      "claim_type": "news_citation",
      "verdict": "verified",
      "evidence": "recent_deals[].title=Kestrabel Ventures leads EUR 3.5M Seed in Rukvane Security (2026-04-15)"
    },
    {
      "claim_text": "so it is still actively leading cybersecurity seed rounds",
      "claim_type": "timing_signal",
      "verdict": "unverifiable",
      "evidence": null
    },
    {
      "claim_text": "It also backed Glintmark Labs (2022), a tool that flags risky dependency upgrades before code is merged",
      "claim_type": "portfolio_company",
      "verdict": "verified",
      "evidence": "portfolio_companies[].name=Glintmark Labs (description: [Kestrabel Ventures, 2022] Static-analysis service that flags risky dependency upgrades before merge)"
    },
    {
      "claim_text": "Kestrabel is the only match in a 30-firm demo dataset.",
      "claim_type": "other",
      "verdict": "unverifiable",
      "evidence": null
    },
    {
      "claim_text": "It's three companies in total, and only two are in security.",
      "claim_type": "portfolio_company",
      "verdict": "verified",
      "evidence": "firm_profiles[0].portfolio_count=3; firm_profiles[1].focus_areas=[cybersecurity: 2, devtools: 1]"
    },
    {
      "claim_text": "The portfolio lists the investment in 2025, but the news item dates the seed round to April 2026.",
      "claim_type": "news_citation",
      "verdict": "verified",
      "evidence": "portfolio_companies[].description=[Kestrabel Ventures, 2025] (Rukvane Security); recent_deals[].title=...Rukvane Security (2026-04-15)"
    },
    {
      "claim_text": "Cheque size wasn't checked against a raise.",
      "claim_type": "ticket_band",
      "verdict": "verified",
      "evidence": "firm_profiles[0].fit_note=check size not evaluated"
    }
  ]
}
